sys_script.script:
/**
 * ESR - Set submission defaults   (before / insert / order 100)
 *
 * Stamps the identity and intake fields that every ticket needs, no matter
 * whether the record arrives from a form, a list, the UI page or the REST API.
 * Nothing here depends on another rule having run first.
 */
;(function setSubmissionDefaults(current, previous) {
    var userId = gs.getUserID()

    if (!current.getValue('requester')) {
        current.setValue('requester', userId)
    }

    if (!current.getValue('opened_by')) {
        current.setValue('opened_by', userId)
    }

    if (!current.getValue('opened_at')) {
        current.setValue('opened_at', new GlideDateTime().getValue())
    }

    if (!current.getValue('state')) {
        current.setValue('state', '1')
    }

    if (!current.getValue('impact')) {
        current.setValue('impact', '3')
    }

    if (!current.getValue('urgency')) {
        current.setValue('urgency', '3')
    }

    current.setValue('active', true)
})(current, previous)
